/* Separate host work/component report. Old floor counters are not reassigned. */
static bool floor_world_write_report(const char*prefix,const bounce_floor_world_work*w,bool enabled,bool complete){
 char path[4096];snprintf(path,sizeof path,"%s.floor-world.json",prefix);FILE*f=fopen(path,"w");if(!f)return false;
 fprintf(f,"{\"version\":\"floor-world-v1\",\"enabled\":%s,\"complete\":%s,\"workBytes\":%zu,\"componentBytes\":%zu,\"innerSamples\":16,\"shaderLimit\":%llu,\"hitLimit\":%llu,\"workLimit\":%llu,\"workUsed\":%llu,\"shaderCalls\":%llu,\"evaluations\":%llu,\"queries\":%llu,\"misses\":%llu,\"blockedFloor\":%llu,\"blockedCharacter\":%llu,\"visibilityRays\":%llu,\"visibilityNodeVisits\":%llu,\"visibilityTriangleTests\":%llu,\"sameTransportBudget\":true,\"old8MCombinedAdmission\":false}\n",enabled?"true":"false",complete?"true":"false",sizeof*w,sizeof(bounce_floor_world_result),(unsigned long long)w->shader_limit,(unsigned long long)w->hit_limit,(unsigned long long)w->work_limit,(unsigned long long)w->work_used,(unsigned long long)w->shader_calls,(unsigned long long)w->evaluations,(unsigned long long)w->queries,(unsigned long long)w->misses,(unsigned long long)w->blocked_floor,(unsigned long long)w->blocked_character,(unsigned long long)w->visibility_used.rays,(unsigned long long)w->visibility_used.node_visits,(unsigned long long)w->visibility_used.triangle_tests);
 return fclose(f)==0;
}
